<?php $e = static fn($value) => htmlspecialchars((string)($value ?? ''),ENT_QUOTES,'UTF-8'); ?>
<?php if($message): ?><div class="notice success"><?= $e($message) ?></div><?php endif; ?><?php if($error): ?><div class="notice error"><?= $e($error) ?></div><?php endif; ?>
