<?php elseif($page==='overview'): ?><div class="welcome"><div><span class="eyebrow">VOTRE ESPACE</span><h2>Bonjour, <?= $e($profile['prenom']) ?> 👋</h2><p>Consultez vos modules, suivez vos étudiants et gérez leurs notes.</p></div><div class="welcome-icon">✦</div></div><div class="stats-grid"><article class="stat-card"><span>Mes modules</span><strong><?= (int)$stats[0] ?></strong><small>Enseignements attribués</small></article><article class="stat-card"><span>Évaluations</span><strong><?= (int)$stats[1] ?></strong><small>Dans mes enseignements</small></article><article class="stat-card"><span>Notes saisies</span><strong><?= (int)$stats[2] ?></strong><small>Notes enregistrées</small></article></div><div class="section-heading"><div><span class="eyebrow">RÉCAPITULATIF</span><h2>Mes enseignements</h2></div><a class="text-link" href="?route=professor&amp;page=modules">Tout afficher →</a></div><?php $records=$overviewModules; $columns=$overviewColumns; require dirname(__DIR__).'/shared/table.php'; ?>
<?php elseif($page==='profile'): ?><div class="profile-card"><div class="profile-avatar"><?= $e(mb_substr($profile['prenom'],0,1).mb_substr($profile['nom'],0,1)) ?></div><div><span class="eyebrow">PROFIL ACADÉMIQUE</span><h2><?= $e($profile['prenom'].' '.$profile['nom']) ?></h2><p><?= $e($_SESSION['user_email']??'') ?></p></div></div><div class="detail-grid"><?php foreach($profile as $key=>$value): ?><div class="detail-item"><span><?= $e(ucfirst(str_replace('_',' ',$key))) ?></span><b><?= $e($value?:'—') ?></b></div><?php endforeach; ?></div>
<?php elseif($page==='notifications'): ?><?php $emptyTitle='Vous êtes à jour'; $emptyMessage='Le schéma SQL actuel ne contient pas de table de notifications. Aucun contenu factice n’est affiché.'; require dirname(__DIR__).'/shared/empty-state.php'; ?>
<?php else: ?>
<?php if($page==='grades'): ?><div class="section-heading"><div><span class="eyebrow">SAISIE / MODIFICATION</span><h2>Enregistrer une note</h2></div></div><form class="grade-form" method="post" action="?route=professor&amp;page=grades"><label>Évaluation<select name="id_evaluation" required><option value="">Choisir une évaluation</option><?php foreach($evaluationOptions as $evaluation): ?><option value="<?= (int)$evaluation['id_evaluation'] ?>"><?= $e($evaluation['code_module'].' · '.$evaluation['libelle'].' ( / '.$evaluation['note_max'].')') ?></option><?php endforeach; ?></select></label><label>Inscription étudiant<select name="id_inscription" required><option value="">Choisir un étudiant</option><?php foreach($registrationOptions as $student): ?><option value="<?= (int)$student['id_inscription'] ?>"><?= $e($student['code_module'].' · '.$student['CNE'].' · '.$student['prenom'].' '.$student['nom']) ?></option><?php endforeach; ?></select></label><label>Note<input type="number" name="valeur" min="0" step="0.01" required placeholder="Ex. 15.50"></label><label>Observation <span class="optional">(facultative)</span><input type="text" name="observation" maxlength="1000" placeholder="Ajouter une observation"></label><button class="primary-button" type="submit" name="save_grade" value="1">Enregistrer la note</button></form><?php endif; ?>
<div class="section-heading"><div><span class="eyebrow">DONNÉES ACADÉMIQUES</span><h2><?= $e($title) ?></h2></div></div><?php if($page==='grades'): ?><div class="table-wrap"><table><thead><tr><?php foreach($columns as $column): if(in_array($column,['id_evaluation','id_inscription'],true)) continue; ?><th><?= $e(ucfirst(str_replace('_',' ',$column))) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($records as $record): ?><tr><?php foreach($columns as $column): if(in_array($column,['id_evaluation','id_inscription'],true)) continue; ?><td><?= $e($record[$column]??'—') ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php else: ?><?php require dirname(__DIR__).'/shared/table.php'; ?><?php endif; ?>
